/// <reference path="./sigApi.Property.d.ts" />
/// <reference path="./sigApi.PropertyWithDataPoints.d.ts" />
/// <reference path="./sigApi.Scheme.d.ts" />

declare namespace SigApi {
    interface PropertyScheme extends PropertyWithDataPoints {
        /**
         * Returns the currently active Property
         * 
         * @returns {Property|null} the currently active Property
         */
        getSelectedProp(): Property | null
        /**
         * Returns the input Property
         * 
         * @returns {Property|null} The Property which is used as input for the scheme
         */
        getInputProp(): Property | null
        /**
         * Returns the used Scheme object
         * 
         * @returns {Scheme|null} the used scheme Object
         */
        getScheme(): Scheme | null
    }
}
